function sourceMeasurementFor(recipe,event,variant=0){
 const mapping=REFERENCE_WEAPON_MAP[recipe?.sourceActor]?.[event];
 const index=Number.isFinite(variant)?Math.abs(Math.trunc(variant)):0;
 const filename=Array.isArray(mapping)?mapping[index%mapping.length]:mapping;
 return filename?REFERENCE_ENTRIES[filename]||null:null;
}
function sourceCoverageSummary(weapons){const actual=[];for(const r of Object.values(weapons))for(const event of r.events){if(sourceMeasurementFor(r,event))actual.push({id:r.id,event,source:(Array.isArray(REFERENCE_WEAPON_MAP[r.sourceActor][event])?REFERENCE_WEAPON_MAP[r.sourceActor][event][0]:REFERENCE_WEAPON_MAP[r.sourceActor][event])});}return actual;}

return {REFERENCE_SOURCE,REFERENCE_ENTRIES,REFERENCE_WEAPON_MAP,sourceMeasurementFor,sourceCoverageSummary};
